import{_ as t,o as a,c as o,ae as d}from"./chunks/framework.BThPlfjz.js";const m=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"Architecture.md","filePath":"Architecture.md"}'),n={name:"Architecture.md"};function r(c,e,s,i,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><hr><h2 id="what-each-layer-owns" tabindex="-1">What each layer owns <a class="header-anchor" href="#what-each-layer-owns" aria-label="Permalink to &quot;What each layer owns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Owns</th></tr></thead><tbody><tr><td><code>.me</code></td><td>Seed derivation, semantic tree, reactivity, memory</td></tr><tr><td><code>cleaker</code></td><td>Namespace binding, surface fallback, triad verification</td></tr><tr><td><code>monad.ai</code></td><td>HTTP surface, kernel exposure, mesh announce/discover</td></tr><tr><td><code>netget</code></td><td>Physical routing, domain → port mapping, SSL, monad placement</td></tr></tbody></table><hr><h2 id="the-node" tabindex="-1">The node <a class="header-anchor" href="#the-node" aria-label="Permalink to &quot;The node&quot;">​</a></h2><p>A node is <em>a machine running netget.</em> It is the physical boundary of the stack:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hostname.local ← node hostname</span></span>
<span class="line"><span>  port 80/443 → netget ← entry point</span></span>
<span class="line"><span>  port 8161 → monad ← suign.cleaker.me kernel</span></span>
<span class="line"><span>  port 3000 → any service  ← additional processes</span></span>
<span class="line"><span>  ~/.get/html/ → landing page ← node identity page</span></span></code></pre></div><p>When you visit <code>hostname.local</code>, you reach the node&#39;s gateway. NetGet reads <code>~/.get/runtime/domain-map.json</code> and routes the request to the correct destination.</p><hr><h2 id="frontends" tabindex="-1">Frontends <a class="header-anchor" href="#frontends" aria-label="Permalink to &quot;Frontends&quot;">​</a></h2><p>Two separate React apps can answer <code>local.netget</code> — never both at once. Which one is live is a config switch (<code>mainServerFrontendMode</code> in <code>xConfig.json</code>), not a matter of which files are newest.</p><table tabindex="0"><thead><tr><th></th><th>Main Server UI</th><th>Local Dev Admin</th></tr></thead><tbody><tr><td>Source</td><td><code>gui/app.tsx</code></td><td><code>src/htmls/Netget-REACT/frontend_local/</code></td></tr><tr><td>Stack</td><td><code>this.gui</code> <code>Theme</code>/<code>Layout</code>, <code>Cleaker</code>, <code>Monad</code> — no router, one screen</td><td><code>this.gui</code> <code>Theme</code>/<code>Layout</code>/<code>LeftBar</code> + React Router, full nav</td></tr><tr><td>Views</td><td><code>.me</code> identity orb (expands into Cleaker) + <code>MonadNamespaceCard</code> (mesh/claims)</td><td><code>/</code> welcome, <code>/home</code> (<code>GatewayDashboard</code>), <code>/domains</code> (CRUD), <code>/logs</code></td></tr><tr><td>Built by</td><td><code>gui/vite.app.config.ts</code> → <code>assets/main-server-ui/dist/</code></td><td><code>npm run dev</code> (<code>:5173</code>, for <code>dev</code> mode) or <code>npm run build</code> → copy to <code>~/.get/dist</code> (for <code>local-dist</code> mode)</td></tr></tbody></table><p><code>mainServerFrontendMode</code> (<code>src/modules/NetGetX/OpenResty/mainServerFrontend.ts</code>) has three values, generated into the nginx <code>location /</code> block by <code>setNginxConfigRoutes.ts</code>:</p><ul><li><strong><code>package-dist</code></strong> (default) — nginx serves the built Main Server UI directly: <code>root $distRoot; try_files $uri /index.html;</code>.</li><li><strong><code>local-dist</code></strong> — same, but from a locally-built copy at <code>~/.get/dist</code> instead of the packaged one.</li><li><strong><code>dev</code></strong> — nginx instead <code>proxy_pass</code>es <code>/</code> to a live Vite dev server (<code>mainServerFrontendDevUrl</code>, default <code>http://127.0.0.1:5173</code>) — i.e. Local Dev Admin, reached live through the gateway instead of a build.</li></ul><p><code>syncMainServerFrontendToHtmlRoot()</code> mirrors whichever build is active into <code>~/.get/html/</code> — the directory this doc&#39;s node diagram calls &quot;landing page&quot; above — so netget always has its own <code>index.html</code> there, independent of whatever else is registered in the domain map for <code>local.netget</code>/<code>localhost</code>/<code>127.0.0.1</code>.</p><p>Both apps share netget&#39;s own compound library (<code>gui/src/{atoms,molecules,compounds}</code> — <code>GatewayDashboard</code>, <code>MonadMesh</code>, <code>GatewayCard</code>, etc.), so they&#39;re different shells around overlapping parts, not unrelated codebases. A third app, <code>frontend_remote</code>, existed alongside these but was never wired into the mode switch above or any build/deploy path — confirmed unreferenced anywhere except a stale <code>tsconfig.json</code> exclude entry pointing at a path that no longer existed — and was removed (2026-08-16).</p><hr><h2 id="hot-reload-architecture" tabindex="-1">Hot-reload architecture <a class="header-anchor" href="#hot-reload-architecture" aria-label="Permalink to &quot;Hot-reload architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.get/runtime/domain-map.json    ← written by netget CLI / generate-domain-map</span></span>
<span class="line"><span>~/.get/runtime/domain-map.version ← bumped on every write</span></span>
<span class="line"><span></span></span>
<span class="line"><span>OpenResty Lua timer (1s):</span></span>
<span class="line"><span>  read version → if changed → reload domain-map → update _G.DOMAIN_MAP</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Result: routing changes take effect in under 1 second, no nginx restart needed.</span></span></code></pre></div><hr><h2 id="domain-store-one-path-not-two" tabindex="-1">Domain store: one path, not two <a class="header-anchor" href="#domain-store-one-path-not-two" aria-label="Permalink to &quot;Domain store: one path, not two&quot;">​</a></h2><p><code>domain-map.json</code> above is generated exclusively from <code>kernel/domainStore.ts</code> (<code>.me</code>-kernel-backed). The HTTP admin API behind <code>Domains.jsx</code> (<code>/domains</code>, <code>/add-domain</code>, <code>/update-domain</code>, <code>/delete-domain</code>, <code>/domains/:parent/subdomains</code>, <code>/provision-cert</code>) goes through the same store now — nginx <code>proxy_pass</code>es each of those to the daemon (<code>localNetget.js</code>), which calls <code>domainStore.ts</code> directly, same shape as <code>/domains/metadata</code>. Used to write to a separate, legacy SQLite database (<code>~/.get/domains.db</code>) that nothing regenerated <code>domain-map.json</code> from — a domain added through the admin API could report success while staying invisible to real routing. Fixed 2026-08-17; full history in <a href="./DomainStoreSplitBrain.html">DomainStoreSplitBrain.md</a>.</p><hr><h2 id="gateway-claims-next-split-brain-to-close" tabindex="-1">Gateway claims: next split-brain to close <a class="header-anchor" href="#gateway-claims-next-split-brain-to-close" aria-label="Permalink to &quot;Gateway claims: next split-brain to close&quot;">​</a></h2><p><code>gateway-claims.json</code> is still the hot-path snapshot nginx Lua reads for signed gateway auth, but it is also still the write-side source of truth. That is the next store to migrate to the same pattern as domains: semantic <code>.me</code> memory as the authoritative ledger, JSON as a materialized cache for Lua.</p><p>See <a href="./GatewayClaimsLedger.html">GatewayClaimsLedger.md</a> for the target paths and migration contract.</p><hr><h2 id="nrp-integration-2026-05-08" tabindex="-1">NRP integration (2026-05-08) <a class="header-anchor" href="#nrp-integration-2026-05-08" aria-label="Permalink to &quot;NRP integration (2026-05-08)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Status</th></tr></thead><tbody><tr><td>Domain → static routing</td><td>✅</td></tr><tr><td>Domain → proxy routing</td><td>✅</td></tr><tr><td>Hot-reload via Lua timer</td><td>✅</td></tr><tr><td>Node landing page (main-server/index.html)</td><td>✅</td></tr><tr><td><code>netget reload</code> CLI (no nginx in PATH needed)</td><td>✅</td></tr><tr><td><code>netget generate-domain-map</code></td><td>✅</td></tr><tr><td>SSL via Let&#39;s Encrypt</td><td>✅</td></tr><tr><td>Dynamic SSL per domain (Lua)</td><td>✅</td></tr><tr><td>Monad mesh routing (<code>.mesh/monads</code>)</td><td>🔲 planned</td></tr><tr><td><code>netget://device/monad</code> resolution</td><td>🔲 planned</td></tr></tbody></table>`,30)])])}const u=t(n,[["render",r]]);export{m as __pageData,u as default};
